"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["56602"],{13249(e){e.exports=JSON.parse('{"id":1839,"title":"2","description":"Please generate a role for our conversation. You can opt for a \'general role\' such as a \'neighbor,\' \'co-worker,\' or \'teacher,\' or a \'specific role\' like \'Steve Jobs, co-founder of Apple\' or \'Jon Snow from Game of Thrones\'. Based on the role you choose, construct an interesting topic and scenario for our conversation.\\n\\nThe scenario should be specific, engaging, and potentially goal-driven, much like a role-playing game scenario. Assign a purpose or goal for each of our roles, and ensure your character adheres to this goal. For instance, if you\'re my neighbor, your objective could be convincing me to join the condo board with you. If you\'re Ross from the TV show \'Friends,\' you might be seeking advice on what gifts to give Rachel.\\n\\nRemember, the aim is to be creative and build a scenario that is truly engaging, rather than one where the characters seem to converse aimlessly.","owner":"\u4EFB\u521A Gavin Ren","upvotes":2,"downvotes":0,"upvoteDifference":2,"updatedAt":"2026-04-13T20:38:17.945Z"}')}}]);